export interface ConnectorConfig {
  /** Trello API key from https://trello.com/app-key */
  trelloApiKey: string;
  /** Trello API token (user-specific) */
  trelloApiToken: string;
  /** The checklist ID on the target Trello card (from URL or API) */
  checklistId: string;
  /** Optional injected fetch for testing */
  fetch?: typeof fetch;
}

export interface GoogleCalendarWebhookPayload {
  type: string;
  created_at: string;
  data: {
    id: string;
    startDate: string;
    duration: number;
    cancelled: boolean;
    eventName: string;
    location: {
      locationType: string;
      onlineMeeting?: {
        url: string;
        id: string;
        passcode: string;
      };
    };
    hosts: Array<{ name: string; email: string }>;
    attendees: Array<{
      name?: string;
      email?: string;
      timezone?: string;
      type: string;
      customQuestionAnswers?: Array<{ question: string; answer: string | string[] }>;
    }>;
    invite: {
      id: string;
      name: string;
      inviteType: string;
      description: string;
    };
  };
}

export interface HandleResult {
  checklistItemId: string;
  checklistId: string;
  boardId: string;
  name: string;
  value: string;
  state: string;
}

async function handle(
  payload: GoogleCalendarWebhookPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch;

  // Validate required fields
  if (!payload.data?.attendees?.length) {
    throw new Error('Payload missing required field: data.attendees (must be non-empty array)');
  }

  const firstAttendee = payload.data.attendees[0];
  const email = firstAttendee.email?.trim();
  const displayName = firstAttendee.name?.trim();

  if (!email && !displayName) {
    throw new Error('First attendee missing both email and name');
  }

  const value = email ?? displayName!;
  const name = 'First Attendee Email';

  // Build Trello API URL with query parameters
  const url = new URL(`https://api.trello.com/1/checklists/${config.checklistId}/checkItems`);
  url.searchParams.set('key', config.trelloApiKey);
  url.searchParams.set('token', config.trelloApiToken);

  const body = JSON.stringify({ name, value });

  const response = await fetchImpl(url.toString(), {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body,
  });

  if (!response.ok) {
    throw new Error(`Trello API error: ${response.status} ${response.statusText} at POST ${url.pathname}`);
  }

  const result = (await response.json()) as {
    id: string;
    idChecklist: string;
    idBoard: string;
    name: string;
    pos: number;
    state: string;
  };

  return {
    checklistItemId: result.id,
    checklistId: result.idChecklist,
    boardId: result.idBoard,
    name: result.name,
    value,
    state: result.state,
  };
}

